/// <summary>
/// Kurt Scerri - 03/03/2021
/// Replication of Microsoft class <c>BankPaymAdviceReportGeneratorVendPosted</c> due to internal class declarations
/// </summary>
class METBankPaymAdviceReportGeneratorVendPosted extends METBankPaymAdviceReportGeneratorVend
{
    private VendTrans vendTransPayment;
    private VendSettlement vendSettlementPayment;
    private VendSettlement vendSettlementInvoice;
    
}

Method.Source:
protected void findInvoicesAndCreateData() { Voucher voucher; LedgerTransVoucherLink voucherLink, journalVoucherLink;
if (ledgerJournalTrans.Company != ledgerJournalTrans.DataAreaId) { //get VoucherGroupId select firstonly VoucherGroupId from journalVoucherLink where journalVoucherLink.Voucher == ledgerJournalTrans.Voucher;
while select crosscompany vendTransPayment where vendTransPayment.AccountNum == vendTable.AccountNum && vendTransPayment.TransDate == ledgerJournalTrans.TransDate && vendTransPayment.DataAreaId == ledgerJournalTrans.Company && vendTransPayment.Cancel == NoYes::Yes join vendSettlementPayment where vendSettlementPayment.TransRecId == vendTransPayment.RecId && vendSettlementPayment.CanBeReversed == NoYes::Yes && vendSettlementPayment.TransCompany == vendTransPayment.DataAreaId && vendSettlementPayment.AccountNum == vendTransPayment.AccountNum exists join voucherLink where voucherLink.Voucher == vendTransPayment.Voucher && voucherLink.VoucherGroupId == journalVoucherLink.VoucherGroupId && voucherLink.DataAreaId == ledgerJournalTrans.Company { select firstonly crosscompany vendTransInvoice where vendTransInvoice.RecId == vendSettlementPayment.OffsetRecid && vendTransInvoice.DataAreaId == vendSettlementPayment.OffsetCompany && vendTransInvoice.Cancel == NoYes::Yes join vendSettlementInvoice where vendSettlementInvoice.TransRecId == vendTransInvoice.RecId && vendSettlementInvoice.TransCompany == vendTransInvoice.DataAreaId && vendSettlementInvoice.AccountNum == vendTransInvoice.AccountNum && vendSettlementInvoice.OffsetRecid == vendTransPayment.RecId && vendSettlementInvoice.CanBeReversed == NoYes::Yes;
this.insertBankPaymAdviceTmp(); } } else { while select crosscompany vendTransPayment where vendTransPayment.Voucher == ledgerJournalTrans.Voucher && vendTransPayment.AccountNum == vendTable.AccountNum && vendTransPayment.TransDate == ledgerJournalTrans.TransDate && vendTransPayment.DataAreaId == ledgerJournalTrans.Company && vendTransPayment.Cancel == NoYes::Yes join vendSettlementPayment where vendSettlementPayment.TransRecId == vendTransPayment.RecId && vendSettlementPayment.CanBeReversed == NoYes::Yes && vendSettlementPayment.TransCompany == vendTransPayment.DataAreaId && vendSettlementPayment.AccountNum == vendTransPayment.AccountNum { select firstonly crosscompany vendTransInvoice where vendTransInvoice.RecId == vendSettlementPayment.OffsetRecid && vendTransInvoice.DataAreaId == vendSettlementPayment.OffsetCompany && vendTransInvoice.Cancel == NoYes::Yes join vendSettlementInvoice where vendSettlementInvoice.TransRecId == vendTransInvoice.RecId && vendSettlementInvoice.TransCompany == vendTransInvoice.DataAreaId && vendSettlementInvoice.AccountNum == vendTransInvoice.AccountNum && vendSettlementInvoice.OffsetRecid == vendTransPayment.RecId && vendSettlementInvoice.CanBeReversed == NoYes::Yes;
this.insertBankPaymAdviceTmp(); } } }

protected void populateBankPaymAdviceTempPaymentInfo()
{
    bankPaymAdviceTmp.PaymRefLabel = this.getPaymRefLabel();
    bankPaymAdviceTmp.PaymentReference = this.getPaymRef();
    bankPaymAdviceTmp.SettledCurrencyCode = this.getPaymentCurrencyCode();
    bankPaymAdviceTmp.CashDisc = this.getCashDiscAmount();
    bankPaymAdviceTmp.TransDate = ledgerJournalTrans.TransDate;
    bankPaymAdviceTmp.Balance01 = vendSettlementPayment.SettleAmountCur;
    bankPaymAdviceTmp.METCheque = ledgerJournalTrans.BankChequeNum;
}

protected Amount getCashDiscAmount()
{
    return this.calculateAmountInPaymentCurrency(vendSettlementInvoice.TransDate, vendTransInvoice.CurrencyCode, vendSettlementInvoice.UtilizedCashDisc);
}
